package io.knowledgebrain.learning;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import java.util.function.Supplier;
import java.security.MessageDigest;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;
import io.knowledgebrain.contracts.learning.conceptevidence.v1.*;

/** Learning owns this relationship. The external Concept is checked through its owner API. */
final class ConceptEvidenceStore {
 record Evidence(UUID evidenceId,UUID roadmapId,UUID spaceId,UUID nodeId,String nodeTitle,String visibility,String state,long version,UUID conceptSpaceId,UUID conceptId,long conceptVersion,String conceptTitle,String conceptVisibility,String memo,String createdAt,String updatedAt){}
 record Input(UUID nodeId,UUID conceptSpaceId,UUID conceptId,long conceptVersion,String memo){}
 record Recorded(Evidence evidence,boolean created){}
 record Page(List<Evidence> items,UUID nextAfter){}
 record Revision(UUID revisionId,UUID evidenceId,long version,UUID actorId,String occurredAt,Evidence snapshot){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final RoadmapStore roadmaps;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 ConceptEvidenceStore(DataSource ds,Clock clock,RoadmapStore roadmaps){jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);this.roadmaps=roadmaps;}
 private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Learning evidence unavailable");}
 private static ResponseStatusException conflict(String reason){return new ResponseStatusException(HttpStatus.CONFLICT,reason);}
 private static void trace(String value){if(value==null||!value.matches("[0-9a-f]{32}")||value.equals("0".repeat(32)))throw LearningStudyStore.bad();}
 private static void memo(String value){RoadmapGraph.text("Evidence",value,8192);}
 private static void active(RoadmapStore.Roadmap root){if(!root.state().equals("ACTIVE"))throw missing();}
 private String node(UUID roadmap,UUID id){var rows=jdbc.query("SELECT title FROM roadmap_node WHERE roadmap_id=? AND node_id=? AND state='ACTIVE'",(rs,n)->rs.getString(1),roadmap,id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private Evidence read(UUID space,UUID roadmap,UUID id,boolean active){RoadmapGraph.id(space);RoadmapGraph.id(roadmap);RoadmapGraph.id(id);var rows=jdbc.query("SELECT e.version,e.state,v.snapshot::text FROM roadmap r JOIN learning_evidence e ON e.roadmap_id=r.roadmap_id JOIN learning_evidence_revision v ON v.evidence_id=e.evidence_id AND v.version=e.version WHERE r.space_id=? AND r.roadmap_id=? AND e.evidence_id=? AND e.kind='CONCEPT'"+(active?" AND e.state='ACTIVE'":""),(rs,n)->decode(rs.getString(3),space,roadmap,id,rs.getLong(1),rs.getString(2)),space,roadmap,id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private Evidence decode(String raw,UUID space,UUID roadmap,UUID id,long version,String state){var e=json.readValue(raw,Evidence.class);if(!e.spaceId().equals(space)||!e.roadmapId().equals(roadmap)||!e.evidenceId().equals(id)||e.version()!=version||!e.state().equals(state)||!e.visibility().equals("PRIVATE"))throw new IllegalStateException("Evidence revision mismatch");return e;}
 Evidence get(UUID space,UUID roadmap,UUID id){return read(space,roadmap,id,true);}
 Recorded record(UUID space,UUID roadmap,UUID actor,String key,Input input,String trace,Supplier<ConceptReferenceClient.Reference> check){
  RoadmapGraph.id(actor);trace(trace);if(input==null||input.conceptVersion()<1||key==null||!key.matches("[0-9a-f]{32}"))throw LearningStudyStore.bad();RoadmapGraph.id(input.nodeId());RoadmapGraph.id(input.conceptId());RoadmapGraph.id(input.conceptSpaceId());memo(input.memo());String fingerprint;try{fingerprint=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(input)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}final String hash=fingerprint;
  return tx.execute(s->{var root=roadmaps.lock(space,roadmap);var existing=jdbc.query("SELECT evidence_id,request_fingerprint,kind FROM learning_evidence WHERE roadmap_id=? AND request_key=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class),rs.getString(2)+":"+rs.getString(3)),roadmap,key);if(!existing.isEmpty()){var prior=existing.getFirst();if(!prior.getValue().equals(hash+":CONCEPT"))throw conflict("Request key already used");return new Recorded(read(space,roadmap,prior.getKey(),false),false);}active(root);String nodeTitle=node(roadmap,input.nodeId());if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_evidence WHERE roadmap_id=? AND node_id=? AND kind='CONCEPT' AND concept_space_id=? AND concept_id=? AND concept_version=? AND state='ACTIVE')",Boolean.class,roadmap,input.nodeId(),input.conceptSpaceId(),input.conceptId(),input.conceptVersion())))throw conflict("Concept version already linked to this node");
   var ref=check.get();if(ref==null||!space.equals(ref.spaceId())||!input.conceptId().equals(ref.conceptId())||!actor.equals(ref.principalId())||ref.version()!=input.conceptVersion()||!input.conceptSpaceId().equals(ref.conceptSpaceId())||!("PUBLIC".equals(ref.visibility())||("PRIVATE".equals(ref.visibility())&&space.equals(ref.conceptSpaceId()))))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Invalid owner reference");RoadmapGraph.text(ref.title(),"",0);var now=clock.instant();var e=new Evidence(ids.next(),roadmap,space,input.nodeId(),nodeTitle,"PRIVATE","ACTIVE",1,input.conceptSpaceId(),input.conceptId(),input.conceptVersion(),ref.title(),ref.visibility(),input.memo(),now.toString(),now.toString());jdbc.update("INSERT INTO learning_evidence(evidence_id,roadmap_id,node_id,state,version,kind,concept_space_id,concept_id,concept_version,concept_visibility,request_key,request_fingerprint) VALUES (?,?,?,'ACTIVE',1,'CONCEPT',?,?,?,?,?,?)",e.evidenceId(),roadmap,input.nodeId(),input.conceptSpaceId(),input.conceptId(),input.conceptVersion(),ref.visibility(),key,hash);revision(e,actor,trace,"ConceptLearningEvidenceLinked",now);return new Recorded(e,true);});
 }
 Evidence change(UUID space,UUID roadmap,UUID id,UUID actor,long expected,String memo,boolean retire,String trace){RoadmapGraph.id(actor);trace(trace);if(expected<1)throw LearningStudyStore.bad();if(!retire)memo(memo);return tx.execute(s->{active(roadmaps.lock(space,roadmap));var prior=read(space,roadmap,id,true);if(prior.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Evidence changed; inspect latest before saving");if(!retire&&prior.memo().equals(memo))return prior;var now=clock.instant();var e=new Evidence(id,roadmap,space,prior.nodeId(),prior.nodeTitle(),"PRIVATE",retire?"RETIRED":"ACTIVE",prior.version()+1,prior.conceptSpaceId(),prior.conceptId(),prior.conceptVersion(),prior.conceptTitle(),prior.conceptVisibility(),retire?prior.memo():memo,prior.createdAt(),now.toString());jdbc.update("UPDATE learning_evidence SET state=?,version=? WHERE evidence_id=?",e.state(),e.version(),id);revision(e,actor,trace,retire?"ConceptLearningEvidenceRetired":"ConceptLearningEvidenceUpdated",now);return e;});}
 Page page(UUID space,UUID roadmap,UUID after,int limit){roadmaps.inspect(space,roadmap);if(after!=null)RoadmapGraph.id(after);if(limit<1||limit>100)throw LearningStudyStore.bad();var args=after==null?new Object[]{space,roadmap,limit+1}:new Object[]{space,roadmap,after,limit+1};var rows=jdbc.query("SELECT e.evidence_id,e.version,e.state,v.snapshot::text FROM roadmap r JOIN learning_evidence e ON e.roadmap_id=r.roadmap_id JOIN learning_evidence_revision v ON v.evidence_id=e.evidence_id AND v.version=e.version WHERE r.space_id=? AND r.roadmap_id=? AND e.state='ACTIVE' AND e.kind='CONCEPT'"+(after==null?"":" AND e.evidence_id>?")+" ORDER BY e.evidence_id LIMIT ?",(rs,n)->decode(rs.getString(4),space,roadmap,rs.getObject(1,UUID.class),rs.getLong(2),rs.getString(3)),args);var items=List.copyOf(rows.subList(0,Math.min(rows.size(),limit)));return new Page(items,rows.size()>limit?items.getLast().evidenceId():null);}
 List<Revision> history(UUID space,UUID roadmap,UUID id,long before,int limit){read(space,roadmap,id,false);if(before<1||limit<1||limit>10)throw LearningStudyStore.bad();return jdbc.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM learning_evidence_revision WHERE evidence_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),id,rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Evidence.class)),id,before,limit);}
 private void revision(Evidence e,UUID actor,String trace,String type,Instant now){var revision=ids.next();jdbc.update("INSERT INTO learning_evidence_revision VALUES (?,?,?,?,?,?::jsonb)",revision,e.evidenceId(),e.version(),actor,Timestamp.from(now),json.writeValueAsString(e));var payload=ConceptEvidenceChangedPayloadV1.newBuilder().setEvidenceId(e.evidenceId().toString()).setRevisionId(revision.toString()).setRoadmapId(e.roadmapId().toString()).setNodeId(e.nodeId().toString()).setNodeTitle(e.nodeTitle()).setVersion(e.version()).setState(e.state()).setVisibility("PRIVATE").setConceptSpaceId(e.conceptSpaceId().toString()).setConceptVisibility(e.conceptVisibility()).setConceptId(e.conceptId().toString()).setConceptVersion(e.conceptVersion()).setConceptTitle(e.conceptTitle()).setMemo(e.memo()).setCreatedAt(e.createdAt()).setUpdatedAt(e.updatedAt()).build();var event=ConceptEvidenceEventEnvelopeV1.newBuilder().setEventId(ids.next().toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("learning-service").setAggregateType("ConceptLearningEvidence").setAggregateId(e.evidenceId().toString()).setSpaceId(e.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(payload.toByteString()).build();jdbc.update("INSERT INTO outbox_event VALUES (?,'concept-evidence',?,?,?,?,'learning','concept-evidence-events','1',?)",UUID.fromString(event.getEventId()),e.evidenceId(),type,Timestamp.from(now),trace,event.toByteArray());}
}
